// readApplyInput reads input from --from-file or stdin for apply commands.
// NOTE: Also used by classic_registry.go helpers (same generated package).
func readApplyInput(fromFile string) ([]byte, error) {
	if fromFile != "" {
		data, err := os.ReadFile(fromFile)
		if err != nil {
			return nil, fmt.Errorf("reading input file: %w", err)
		}
		return data, nil
	}

	stat, _ := os.Stdin.Stat()
	if (stat.Mode() & os.ModeCharDevice) == 0 {
		data, err := io.ReadAll(io.LimitReader(os.Stdin, 10<<20))
		if err != nil {
			return nil, fmt.Errorf("reading stdin: %w", err)
		}
		if len(data) > 0 {
			return data, nil
		}
	}

	return nil, fmt.Errorf("input required: use --from-file or pipe data to stdin")
}

// printScaffoldOutput prints a scaffold JSON string, converting to YAML when the
// output format requests it.
// NOTE: Also used by classic_registry.go helpers (same generated package).
func printScaffoldOutput(jsonStr, format string) error {
	if format == "yaml" {
		var v any
		if err := json.Unmarshal([]byte(jsonStr), &v); err != nil {
			return fmt.Errorf("scaffold marshal error: %w", err)
		}
		enc := yaml.NewEncoder(os.Stdout)
		enc.SetIndent(2)
		return enc.Encode(v)
	}
	fmt.Println(jsonStr)
	return nil
}

// normalizeInputToJSON converts YAML input to JSON. JSON input is returned unchanged.
// NOTE: Also used by classic_registry.go helpers (same generated package).
func normalizeInputToJSON(data []byte) ([]byte, error) {
	// Fast path: already JSON
	if json.Valid(data) {
		return data, nil
	}
	// Try YAML → any → JSON
	var v any
	if err := yaml.Unmarshal(data, &v); err != nil {
		return nil, fmt.Errorf("input is not valid JSON or YAML: %w", err)
	}
	out, err := json.Marshal(v)
	if err != nil {
		return nil, fmt.Errorf("re-marshaling YAML as JSON: %w", err)
	}
	return out, nil
}

// extractJSONField extracts a string field from a JSON object.
func extractJSONField(data []byte, field string) (string, error) {
	var obj map[string]any
	if err := json.Unmarshal(data, &obj); err != nil {
		return "", fmt.Errorf("parsing JSON: %w", err)
	}
	val, ok := obj[field]
	if !ok {
		return "", fmt.Errorf("field %q not found", field)
	}
	s, ok := val.(string)
	if !ok || s == "" {
		return "", fmt.Errorf("field %q must be a non-empty string", field)
	}
	return s, nil
}

// resolveNameToIDForApply looks up a resource by name and returns its ID.
// Unlike resolveNameToID, it fetches enough results to detect collisions.
// Returns ("", nil) when no resource is found (caller should create).
// Returns (id, nil) when exactly one match is found.
// Returns ("", error) when multiple matches or lookup fails.
func resolveNameToIDForApply(ctx context.Context, client registry.HTTPClient, listPath, nameField, idField, name string, noInput bool) (string, error) {
	// Escape double quotes in name to prevent RSQL injection
	escapedName := strings.ReplaceAll(name, `"`, `\"`)
	filterPath := fmt.Sprintf("%s?filter=%s&page-size=100",
		listPath, url.QueryEscape(fmt.Sprintf(`%s=="%s"`, nameField, escapedName)))

	resp, err := client.Do(ctx, "GET", filterPath, nil)
	if err != nil {
		return "", fmt.Errorf("looking up %q: %w", name, err)
	}
	defer func() { _ = resp.Body.Close() }()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", fmt.Errorf("reading lookup response: %w", err)
	}

	var data struct {
		TotalCount int               `json:"totalCount"`
		Results    []json.RawMessage `json:"results"`
	}
	if err := json.Unmarshal(body, &data); err != nil {
		var arr []json.RawMessage
		if jsonErr := json.Unmarshal(body, &arr); jsonErr != nil {
			return "", fmt.Errorf("parsing lookup response: %w", err)
		}
		data.Results = arr
		data.TotalCount = len(arr)
	}

	if data.TotalCount == 0 || len(data.Results) == 0 {
		return "", nil // Not found — caller should create
	}

	// Client-side filter: some endpoints ignore RSQL filter params (e.g. prestages).
	// Always apply exact name matching to guard against false positives.
	results := filterResultsByName(data.Results, nameField, name)
	if len(results) == 0 {
		return "", nil // Not found — caller should create
	}

	// Parse results to extract IDs
	type applyMatch struct {
		id string
	}
	var matches []applyMatch
	for _, raw := range results {
		var obj map[string]any
		if err := json.Unmarshal(raw, &obj); err != nil {
			continue
		}
		if id := extractIDString(obj, idField); id != "" {
			matches = append(matches, applyMatch{id: id})
		}
	}

	if len(matches) == 0 {
		return "", nil
	}

	if len(matches) == 1 {
		return matches[0].id, nil
	}

	// Collision: multiple resources with the same name
	if noInput {
		ids := make([]string, len(matches))
		for i, m := range matches {
			ids[i] = m.id
		}
		return "", fmt.Errorf("multiple resources found with name %q (IDs: %s); resolve duplicates or use update with a specific ID", name, strings.Join(ids, ", "))
	}

	// Interactive: prompt user to pick
	fmt.Fprintf(os.Stderr, "Multiple resources found with name %q:\n", name)
	for i, m := range matches {
		fmt.Fprintf(os.Stderr, "  [%d] ID: %s\n", i+1, m.id)
	}
	fmt.Fprintf(os.Stderr, "Enter number to replace (or 0 to cancel): ")
	var choice int
	if _, err := fmt.Fscan(os.Stdin, &choice); err != nil || choice < 1 || choice > len(matches) {
		return "", fmt.Errorf("aborted")
	}
	return matches[choice-1].id, nil
}

// buildMergePatchFromSet converts a slice of "key.path=value" strings into a
// JSON merge-patch document. Dot notation is expanded into nested objects.
// Value inference: "true"/"false" → bool, "null" → null, integers → int64, else string.
func buildMergePatchFromSet(pairs []string) ([]byte, error) {
	result := make(map[string]any)
	for _, pair := range pairs {
		eq := strings.Index(pair, "=")
		if eq < 1 {
			return nil, fmt.Errorf("invalid --set value %q: expected key=value", pair)
		}
		key := pair[:eq]
		val := pair[eq+1:]
		if err := setNestedValue(result, strings.Split(key, "."), parsePatchValue(val)); err != nil {
			return nil, fmt.Errorf("setting %q: %w", key, err)
		}
	}
	return json.Marshal(result)
}

// setNestedValue sets a value at a dot-notation path within a nested map.
func setNestedValue(m map[string]any, keys []string, value any) error {
	if len(keys) == 1 {
		m[keys[0]] = value
		return nil
	}
	sub, ok := m[keys[0]]
	if !ok {
		sub = make(map[string]any)
		m[keys[0]] = sub
	}
	subMap, ok := sub.(map[string]any)
	if !ok {
		return fmt.Errorf("cannot set nested key under non-object field %q", keys[0])
	}
	return setNestedValue(subMap, keys[1:], value)
}

// parsePatchValue converts a string to the most appropriate scalar type for
// JSON merge-patch: "true"/"false" → bool, "null" → nil, integers → int64, else string.
func parsePatchValue(s string) any {
	switch s {
	case "true":
		return true
	case "false":
		return false
	case "null":
		return nil
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return i
	}
	return s
}

// fetchVersionLock GETs a resource and returns the raw response body.
// The caller uses this to extract versionLock values for optimistic locking.
func fetchVersionLock(ctx context.Context, client registry.HTTPClient, getPath string) ([]byte, error) {
	resp, err := client.Do(ctx, "GET", getPath, nil)
	if err != nil {
		return nil, fmt.Errorf("fetching resource for version lock: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("reading version lock response: %w", err)
	}
	return body, nil
}

// injectVersionLocks deep-merges all versionLock fields from a GET response
// into the user-provided request body. This ensures optimistic locking fields
// are current without requiring users to manually fetch and set them.
func injectVersionLocks(data, serverResponse []byte) ([]byte, error) {
	var dst, src map[string]any
	if err := json.Unmarshal(data, &dst); err != nil {
		return data, nil // unparseable input — pass through unchanged
	}
	if err := json.Unmarshal(serverResponse, &src); err != nil {
		return data, fmt.Errorf("parsing server response for version lock: %w", err)
	}
	mergeVersionLocks(dst, src)
	out, err := json.Marshal(dst)
	if err != nil {
		return data, nil
	}
	return out, nil
}

// mergeVersionLocks recursively copies versionLock fields from src into dst.
func mergeVersionLocks(dst, src map[string]any) {
	if vl, ok := src["versionLock"]; ok {
		dst["versionLock"] = vl
	}
	for key, srcVal := range src {
		srcObj, ok := srcVal.(map[string]any)
		if !ok {
			continue
		}
		dstVal, ok := dst[key]
		if !ok {
			continue
		}
		dstObj, ok := dstVal.(map[string]any)
		if !ok {
			continue
		}
		mergeVersionLocks(dstObj, srcObj)
	}
}

// setVersionLockZero recursively sets all versionLock fields to 0 in the JSON document.
// Used when creating new resources that require optimistic locking.
func setVersionLockZero(data []byte) []byte {
	var obj map[string]any
	if err := json.Unmarshal(data, &obj); err != nil {
		return data
	}
	zeroVersionLocks(obj)
	out, err := json.Marshal(obj)
	if err != nil {
		return data
	}
	return out
}

// zeroVersionLocks recursively sets all versionLock fields to 0.
func zeroVersionLocks(obj map[string]any) {
	if _, ok := obj["versionLock"]; ok {
		obj["versionLock"] = 0
	}
	for _, v := range obj {
		if nested, ok := v.(map[string]any); ok {
			zeroVersionLocks(nested)
		}
	}
}
